head.script:
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.checkValue = function(id, value) {
    if (WebSquare.wUnit.getDomById($p.id + id).textContent == value) {
        return true;
    }
    return false
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 gridView column에 각각 '3333333.33'값을 입력하고 enterkey를 실행한다.
    //1. After executing the sample, enter the value '3333333.33' in the gridview column and execute enterkey.
    //Verify step 1. The value '3333333.33' is entered normally for each item.
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'grid1_cell_0_0')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_grid1__column2').setValue('3333333.33')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1_dataLayer').click()");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'grid1_cell_0_0', '3,333,333.33')", "true");
    //
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'grid1_cell_0_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_grid1__dynamic_text_0_1').setValue('3333333.33')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1_dataLayer').click()");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'grid1_cell_0_1', '3,333,333.33')", "true");
    //
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'grid1_cell_0_2')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_grid1__dynamic_text_0_2').setValue('3333333.33')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1_dataLayer').click()");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'grid1_cell_0_2', '3,333,333.33')", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    grid1.setRef({
        ref: "vector",
        baseNode: "vector",
        repeatNode: "data"
    });
    grid1.insertRow();
    //		grid1.setCellInputType( 0, 0, { inputType : "text",options : {dataType:"float",maxlength:"7.2",displayFormat:"#,###.##",applyFormat:"all"} });
    grid1.setCellInputType(0, 1, {
        inputType: "text",
        options: {
            dataType: "float",
            maxlength: "7.2",
            displayFormat: "#,###.#0",
            applyFormat: "all"
        }
    });
    grid1.setCellInputType(0, 2, {
        inputType: "text",
        options: {
            dataType: "float",
            applyFormat: "all"
        }
    });
    grid1.setCellMaxLength(0, 2, "7.2");
    grid1.setCellDisplayFormat(0, 2, "#,###.#0");
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 23-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
